'use strict';

const FETCH_TIMEOUT = 8000;
const MAX_HTML = 1.5 * 1024 * 1024; // cap parsed HTML

function normalizeUrl(raw) {
  const s = (raw || '').trim();
  if (!s) return null;
  const withProto = /:\/\//.test(s) ? s : 'https://' + s;
